import { sendToastMessage } from "@/functions/messages/toastMessage";

export function fmtCompact(v: number): string {
    if (!Number.isFinite(v)) return 'R$ 0';
    const abs = Math.abs(v);
    const sign = v < 0 ? '-' : '';
    if (abs >= 1_000_000)
        return `${sign}R$ ${(abs / 1_000_000).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })}M`;
    if (abs >= 1_000)
        return `${sign}R$ ${(abs / 1_000).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })}k`;
    return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
import { addYears, differenceInDays, differenceInMonths, differenceInYears, parseISO } from 'date-fns';
import { TagVariant } from "../types";

export function formatDate(dateString: string): string {
    const date = new Date(dateString);
    const months = [
        'JAN',
        'FEV',
        'MAR',
        'ABR',
        'MAI',
        'JUN',
        'JUL',
        'AGO',
        'SET',
        'OUT',
        'NOV',
        'DEZ',
    ];
    return `${months[date.getUTCMonth()]}/${date.getUTCFullYear()}`;
}

/**
 * Formata a duração entre duas datas em uma string legível (anos e meses).
 * @param initialDate Data inicial no formato "YYYY-MM-DD".
 * @param finalDate Data final no formato "YYYY-MM-DD".
 * @returns String formatada (ex: "1 ano e 3 meses").
 */

